{"content":"def expired_keys(records, now):
    """Return expired keys in input order, without changing records."""
    result = []
    for row in records:
        expires_at = row.get("expires_at")
        if expires_at is None:
            continue
        if expires_at <= now:
            result.append(row["key"])
    return result
